#include <iostream>
#include <vector>
#include <string>
#include <cctype>

using namespace std;

/**
 * Problem: 10552 - Automated Judge Script
 * 
 * 解題思路：
 * 1. Accepted: 完全一致（包含所有字元與換行）。
 * 2. Presentation Error: 過濾掉非數字字元後，數字序列一致。
 * 3. Wrong Answer: 其他情況。
 * 
 * 注意：
 * - 輸入包含多行字串，需使用 getline。
 * - 第一行 n 為標準答案行數，接著 m 為團隊輸出行數。
 */

string getDigits(const vector<string>& lines) {
    string digits = "";
    for (const string& s : lines) {
        for (char c : s) {
            if (isdigit(c)) digits += c;
        }
    }
    return digits;
}

int main() {
    int n, m, caseNum = 1;
    while (cin >> n && n != 0) {
        cin.ignore();
        vector<string> sol(n);
        for (int i = 0; i < n; ++i) getline(cin, sol[i]);

        cin >> m;
        cin.ignore();
        vector<string> team(m);
        for (int i = 0; i < m; ++i) getline(cin, team[i]);

        cout << "Run #" << caseNum++ << ": ";

        // 檢查 Accepted
        if (n == m) {
            bool match = true;
            for (int i = 0; i < n; ++i) {
                if (sol[i] != team[i]) {
                    match = false; break;
                }
            }
            if (match) {
                cout << "Accepted" << endl;
                continue;
            }
        }

        // 檢查 Presentation Error
        if (getDigits(sol) == getDigits(team)) {
            cout << "Presentation Error" << endl;
        } else {
            cout << "Wrong Answer" << endl;
        }
    }
    return 0;
}

